#pragma once

#include "CoreMinimal.h"
#include "UI/JamMenuRules.h"

/**
 * The menu's settings in the engine (T-092): graphics quality, window mode and resolution through UGameUserSettings,
 * the three volumes and the difficulty in GameUserSettings.ini under [/Script/JamGame.JamVolumes]. Glue only: the menu's decisions are in
 * JamMenuRules.
 */
namespace JamSettings
{
/** What is set now, and the resolutions the screen offers (the current one among them). */
JAMGAME_API FJamMenuSettings Load(TArray<FIntPoint>& OutResolutions);

/** Applies and saves the quality, the window mode and the resolution. */
JAMGAME_API void ApplyGraphics(const FJamMenuSettings& Settings, const TArray<FIntPoint>& Resolutions);

/**
 * A window saved larger than the desktop (an earlier build, another screen) is made to fit it, and saved so (the
 * author's 5v run). Not for a run whose window the command line sets.
 */
JAMGAME_API void FitSavedWindow();

/** T-101: saves the difficulty; the fight takes it at the next NEW GAME. */
JAMGAME_API void SaveDifficulty(const FJamMenuSettings& Settings);

/** Saves the three volumes; the master one is applied here, the music and the voice by their actors. */
JAMGAME_API void ApplyVolumes(const FJamMenuSettings& Settings, const UObject* WorldContext);
} // namespace JamSettings
#include "Game/JamSettings.h"

#include "AudioDevice.h"
#include "Engine/Engine.h"
#include "Engine/World.h"
#include "GameFramework/GameUserSettings.h"
#include "Kismet/KismetSystemLibrary.h"
#include "Misc/ConfigCacheIni.h"

namespace
{
const TCHAR* const VolumeSection = TEXT("/Script/JamGame.JamVolumes");

/** The menu's window modes in the order of JamTexts::WindowNames. */
const EWindowMode::Type WindowModes[] = { EWindowMode::Fullscreen, EWindowMode::WindowedFullscreen, EWindowMode::Windowed };

int32 LoadVolume(const TCHAR* Key)
{
	int32 Steps = JamMenuRules::VolumeSteps;
	GConfig->GetInt(VolumeSection, Key, Steps, GGameUserSettingsIni);
	return FMath::Clamp(Steps, 0, JamMenuRules::VolumeSteps);
}
} // namespace

FJamMenuSettings JamSettings::Load(TArray<FIntPoint>& OutResolutions)
{
	FJamMenuSettings Settings;
	OutResolutions.Reset();
	TArray<FIntPoint> Offered;
	UKismetSystemLibrary::GetSupportedFullscreenResolutions(Offered);
	for (const FIntPoint& Size : Offered)
	{
		OutResolutions.AddUnique(Size);
	}
	if (UGameUserSettings* User = GEngine ? GEngine->GetGameUserSettings() : nullptr)
	{
		const int32 Level = User->GetOverallScalabilityLevel();
		// A custom mix of levels reads as -1: the menu shows it as EPIC until the player picks one.
		Settings.Quality = Level < 0 ? JamMenuRules::QualityCount - 1 : FMath::Min(Level, JamMenuRules::QualityCount - 1);
		for (int32 Index = 0; Index < UE_ARRAY_COUNT(WindowModes); ++Index)
		{
			if (WindowModes[Index] == User->GetFullscreenMode())
			{
				Settings.Window = Index;
			}
		}
		const FIntPoint Now = User->GetScreenResolution();
		Settings.Resolution = OutResolutions.AddUnique(Now);
	}
	Settings.ResolutionCount = OutResolutions.Num();
	Settings.Master = LoadVolume(TEXT("Master"));
	Settings.Music = LoadVolume(TEXT("Music"));
	Settings.Voice = LoadVolume(TEXT("Voice"));
	GConfig->GetInt(VolumeSection, TEXT("Difficulty"), Settings.Difficulty, GGameUserSettingsIni);
	Settings.Difficulty = FMath::Clamp(Settings.Difficulty, 0, JamMenuRules::DifficultyCount - 1);
	return Settings;
}

void JamSettings::ApplyGraphics(const FJamMenuSettings& Settings, const TArray<FIntPoint>& Resolutions)
{
	UGameUserSettings* User = GEngine ? GEngine->GetGameUserSettings() : nullptr;
	if (!User)
	{
		return;
	}
	User->SetOverallScalabilityLevel(FMath::Clamp(Settings.Quality, 0, JamMenuRules::QualityCount - 1));
	const EWindowMode::Type Mode = WindowModes[FMath::Clamp(Settings.Window, 0, JamMenuRules::WindowCount - 1)];
	User->SetFullscreenMode(Mode);
	// Borderless always covers the desktop; the picked resolution is for fullscreen and the window.
	if (Mode == EWindowMode::WindowedFullscreen)
	{
		User->SetScreenResolution(User->GetDesktopResolution());
	}
	else if (Resolutions.IsValidIndex(Settings.Resolution))
	{
		const FIntPoint Picked = Resolutions[Settings.Resolution];
		User->SetScreenResolution(Mode == EWindowMode::Windowed ? JamMenuRules::FitWindow(Picked, User->GetDesktopResolution()) : Picked);
	}
	User->ApplySettings(false);
}

void JamSettings::FitSavedWindow()
{
	UGameUserSettings* User = GEngine ? GEngine->GetGameUserSettings() : nullptr;
	if (!User || User->GetFullscreenMode() != EWindowMode::Windowed)
	{
		return;
	}
	const FIntPoint Saved = User->GetScreenResolution();
	const FIntPoint Fitted = JamMenuRules::FitWindow(Saved, User->GetDesktopResolution());
	if (Fitted != Saved)
	{
		User->SetScreenResolution(Fitted);
		User->ApplySettings(false);
	}
}

void JamSettings::SaveDifficulty(const FJamMenuSettings& Settings)
{
	GConfig->SetInt(VolumeSection, TEXT("Difficulty"), Settings.Difficulty, GGameUserSettingsIni);
	GConfig->Flush(false, GGameUserSettingsIni);
}

void JamSettings::ApplyVolumes(const FJamMenuSettings& Settings, const UObject* WorldContext)
{
	GConfig->SetInt(VolumeSection, TEXT("Master"), Settings.Master, GGameUserSettingsIni);
	GConfig->SetInt(VolumeSection, TEXT("Music"), Settings.Music, GGameUserSettingsIni);
	GConfig->SetInt(VolumeSection, TEXT("Voice"), Settings.Voice, GGameUserSettingsIni);
	GConfig->Flush(false, GGameUserSettingsIni);
	const UWorld* World = WorldContext ? WorldContext->GetWorld() : nullptr;
	if (FAudioDevice* Device = World ? World->GetAudioDeviceRaw() : nullptr)
	{
		Device->SetTransientPrimaryVolume(JamMenuRules::Volume(Settings.Master));
	}
}
#pragma once

#include "CoreMinimal.h"

enum class EJamMenuPage : uint8
{
	Main,
	Settings
};

/** Every row the menu has, on either page, in the order of their labels (JamTexts::MenuItems). */
enum class EJamMenuItem : uint8
{
	NewGame,
	Settings,
	Exit,
	Quality,
	Window,
	Resolution,
	Master,
	Music,
	Voice,
	Back,
	/** T-101: EASY, NORMAL, HARD on the main page, under NEW GAME. */
	Difficulty
};

/** What the player pressed: the arrows (or WASD), Enter, Escape. */
enum class EJamMenuKey : uint8
{
	Up,
	Down,
	Left,
	Right,
	Confirm,
	Back
};

/** What the game has to do after a press. */
enum class EJamMenuAction : uint8
{
	None,
	NewGame,
	Exit,
	/** A volume changed: heard at once. */
	Volume,
	/** The settings page closed: the graphics settings are applied and saved. */
	Graphics,
	/** The difficulty changed: saved, and played from the next NEW GAME. */
	Difficulty
};

/** The settings as the menu shows them: indices and volume steps. */
struct FJamMenuSettings
{
	/** 0 LOW to 3 EPIC, the engine's scalability levels. */
	int32 Quality = 3;
	/** JamTexts::WindowNames: fullscreen, borderless, windowed. */
	int32 Window = 1;
	/** Into the screen's resolutions, ResolutionCount long. */
	int32 Resolution = 0;
	int32 ResolutionCount = 0;
	int32 Master = 10;
	int32 Music = 10;
	int32 Voice = 10;
	/** T-101: JamTexts::DifficultyNames, EASY, NORMAL, HARD; NORMAL by default. */
	int32 Difficulty = 1;
};

struct FJamMenu
{
	EJamMenuPage Page = EJamMenuPage::Main;
	/** The row under the cursor or the arrows, into ItemsOf(Page). */
	int32 Selected = 0;
	FJamMenuSettings Settings;
	/** T-094: the selected row's dropdown is open, with the option under the arrows or the pointer. */
	bool bListOpen = false;
	int32 ListSelected = 0;
	/** The selected row's slider follows the held mouse button. */
	bool bDragging = false;
};

/**
 * Where everything of a page is on a screen, in pixels (T-094). The HUD draws from it and the mouse is tested against
 * it, so what shows is what takes the click.
 */
struct FJamMenuLayout
{
	/** The dark panel behind the settings page; an empty box on the main page. */
	FBox2D Panel = FBox2D(ForceInit);
	/** Each row's band, top to bottom. */
	TArray<FBox2D> Rows;
	/** Each row's control: the dropdown's box or the slider's track; an empty box for an action. */
	TArray<FBox2D> Controls;
	/** The open dropdown's options, top to bottom; none while no list is open. */
	TArray<FBox2D> Options;
};

/**
 * The main menu before the intro (T-092): which rows a page has and what a key or a click does to them. The quality, the
 * window mode and the resolution are dropdowns, the volumes sliders (T-094). A pick from a dropdown applies at once; the
 * side arrows step a graphics value without applying it until the settings page closes, so stepping through
 * resolutions does not flash the screen. Volumes are heard at once. The main page's DIFFICULTY (T-101) is a selector:
 * the side arrows, Enter and its drawn arrows step it round EASY, NORMAL, HARD.
 * Tests: Jam.Menu.*
 */
namespace JamMenuRules
{
inline constexpr int32 ItemCount = 11;
inline constexpr int32 DifficultyCount = 3;
inline constexpr int32 QualityCount = 4;
inline constexpr int32 WindowCount = 3;
inline constexpr int32 VolumeSteps = 10;

JAMGAME_API TArray<EJamMenuItem> ItemsOf(EJamMenuPage Page);

/** One key on the menu: moves the selection, steps a value, changes the page or asks the game to act. */
JAMGAME_API EJamMenuAction Press(FJamMenu& Menu, EJamMenuKey Key);

/** The pointer is over Row of the page (INDEX_NONE: over none): that row becomes the selected one. */
JAMGAME_API void Point(FJamMenu& Menu, int32 Row);

/** The row of Count rows, the first at Top, each RowHeight tall, that Y falls in; INDEX_NONE outside them. */
JAMGAME_API int32 RowAt(float Y, float Top, float RowHeight, int32 Count);

/** The volume multiplier of a number of steps. */
JAMGAME_API float Volume(int32 Steps);

/** The quality, the window mode and the resolution open a list; the volumes are sliders. */
JAMGAME_API bool IsList(EJamMenuItem Item);
JAMGAME_API bool IsSlider(EJamMenuItem Item);

/** T-101: the difficulty is a selector, < NORMAL >: its arrows step it round its levels. */
JAMGAME_API bool IsSelector(EJamMenuItem Item);

/** How many options Item's list has: the qualities, the window modes, the screen's resolutions; 0 for other rows. */
JAMGAME_API int32 OptionCount(const FJamMenuSettings& Settings, EJamMenuItem Item);

/** Where the page's rows, controls and open list are on a screen of Screen pixels. */
JAMGAME_API FJamMenuLayout Layout(const FJamMenu& Menu, const FVector2D& Screen);

/** The pointer moved to At: the row, or the option of the open list, under it becomes the selected one. */
JAMGAME_API void Hover(FJamMenu& Menu, const FJamMenuLayout& Layout, const FVector2D& At);

/**
 * A left click at At: an action row confirms, a dropdown opens its list, a slider's track takes the value under the
 * pointer and starts a drag. With a list open, a click on an option picks it and anywhere else closes the list.
 */
JAMGAME_API EJamMenuAction Click(FJamMenu& Menu, const FJamMenuLayout& Layout, const FVector2D& At);

/**
 * The size of a window of Size on a desktop of Desktop pixels: as it is if it fits inside the desktop with room for the
 * title bar and the taskbar, else scaled down, its shape kept, until it does (the author's 5v run: a 3840x2160 window
 * hung off the screen with only its top-left corner on it). A desktop of no size leaves Size alone.
 */
JAMGAME_API FIntPoint FitWindow(const FIntPoint& Size, const FIntPoint& Desktop);

/** The mouse button is still held at At: a dragged slider follows it, even off its track. */
JAMGAME_API EJamMenuAction Drag(FJamMenu& Menu, const FJamMenuLayout& Layout, const FVector2D& At);

/** The mouse button is up: no slider follows it any more. */
JAMGAME_API void Release(FJamMenu& Menu);
} // namespace JamMenuRules
