param([string]$Exe, [string]$Extra = "", [int]$Seconds = 25)
# Starts a packaged Shipping game, waits, reports whether it is alive and whether the NGX DLSS runtime is loaded into it.
$args = "-windowed -resx=1280 -resy=720 -nosplash $Extra"
$p = Start-Process -FilePath $Exe -ArgumentList $args -PassThru
Start-Sleep -Seconds $Seconds
$game = Get-Process -Name "JamGame-Win64-Shipping" -ErrorAction SilentlyContinue | Where-Object { $_.Path -like "*MegaJam2026_dlssrel*" }
if (-not $game) { Write-Output "[smoke] not running after $Seconds s (exit code $($p.ExitCode))"; exit 1 }
Write-Output "[smoke] running after $Seconds s, pid $($game.Id), memory $([int]($game.WorkingSet64 / 1MB)) MB"
$mods = $game.Modules | Where-Object { $_.ModuleName -like "nvngx*" -or $_.ModuleName -like "_nvngx*" }
if ($mods) { $mods | ForEach-Object { Write-Output "[smoke] module $($_.ModuleName) $($_.FileName)" } } else { Write-Output "[smoke] no nvngx module loaded" }
$game | Stop-Process -Force
$p | Stop-Process -Force -ErrorAction SilentlyContinue

